entries[296662] = { ["name"] = "Kräuselnde Welle", ["text"] = "Wirken in 2 sek.\nLady Aschenwind stampft auf den Boden, wodurch alle Korallenstrukturen eine kräuselnde Welle zu ihr zurückkehren lassen.\n\nJede Welle, die sie erreicht, stellt bis zu 10% von ' Gehärteter Panzer ' wieder her und fügt allen Spielercharakteren 4478 Frostschaden zu.\n\nWenn Spielercharaktere eine ' Kräuselnde Welle ' berühren, zerspringt diese und fügt allen Spielercharakteren 4478 Frostschaden zu. Der auslösende Spielercharakter wird dabei ' Durchnässt '." }
