entries[297324] = { ["name"] = "Salzblase", ["text"] = "200 Meter Reichweite\nWirken in 3 sek.\nEntfesselt einen Wasserschwall auf die Position des Ziels, der alle Spielercharaktere innerhalb von 12 Metern in einer Salzblase einschließt und sie so handlungsunfähig macht, bis die Blase zerstört wird. Solange der Spielercharakter eingeschlossen ist, fügt die Blase ihm alle 1.5 Sek. 4105 Naturschaden zu." }
