entries[297564] = { ["name"] = "Aufgeschobenes Urteil", ["text"] = "Sofort\nWenn der Spielercharakter stillsteht, bauen sich Stapel in seinem Körper auf. Bei Bewegung fügt ' Aufgeschobenes Urteil ' dem Spielercharakter basierend auf der Anzahl der Stapel Naturschaden zu und setzt die Anzahl zurück. Bei Ablauf verursacht ' Aufgeschobenes Urteil ' den verbleibenden Schaden des Erlasses." }
entries[297566] = { ["name"] = "Aufgeschobenes Urteil", ["text"] = "100 Meter Reichweite\nSofort\nWenn Ihr stillsteht, baut sich eine Ladung in Eurem Körper auf. Bei Bewegung erleidet Ihr durch ' Aufgeschobenes Urteil ' Naturschaden. Bei Ablauf verursacht ' Aufgeschobenes Urteil ' den verbleibenden Schaden des Erlasses." }
entries[297567] = { ["name"] = "Teleport Players" }
entries[297568] = { ["name"] = "Ring of Hostility", ["text"] = "300 Meter Reichweite\nKanalisiert (Wirken in 7 tagen)\nDer Zaubernde erschafft ein Labyrinth aus Ringen der Feindseligkeit, um Spielercharaktere am Überqueren des Schlachtfelds zu hindern." }
entries[297569] = { ["name"] = "Bernregeneration" }
entries[297571] = { ["name"] = "Ethereal Transmorpher", ["text"] = "Sofort\nSummons an Ethereal Transmorpher that can change your appearance for 55 Min.." }
entries[297572] = { ["name"] = "Tückische Gabe", ["text"] = "Sofort\nNimmt 'N'Zoths Gabe' an, wodurch Eure Meisterschaft 30 Sek. lang um 275 erhöht wird. Währenddessen werdet Ihr alle 1 Sek. mit 'Leid' belegt, was 41 Schattenschaden pro Stapel verursacht. Erneut einsetzen, um 'N'Zoths Gabe' zurückzuweisen und beide Effekte zu entfernen. [(2 Min. Abklingzeit)]" }
entries[297573] = { ["name"] = "Murlocarbeit" }
entries[297574] = { ["name"] = "Hoffnungslosigkeit", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nNimmt allen Spielercharakteren die Hoffnung, sodass sie 10 Sek. lang nicht angreifen oder Zauber wirken können.\n\nSpielercharaktere können nach ihrer verlorenen Hoffnung suchen, um den Effekt vorzeitig zu beenden." }
entries[297575] = { ["name"] = "Faulige Gliedmaße", ["text"] = "30 Meter Reichweite\nSofort\nWirft eine verrottende Gliedmaße an den Zielort, die Gegner innerhalb von 10 Metern für 20 Sek. betäubt.\n\nKann nur auf Inselexpeditionen verwendet werden." }
entries[297576] = { ["name"] = "Bebenbestienhauer", ["text"] = "Animabonus\nSofort\nWenn ein Gegner Euch Schaden zufügt, erleidet er (60% der Zaubermacht) Naturschaden. Wenn der Schaden mindestens 5% Eurer Gesundheit ausmacht, wird der Gegner zurückgestoßen.\n\nDer Rückstoß tritt pro Ziel nur einmal alle 10 Sek. auf.\n(500ms Abklingzeit)" }
entries[297577] = { ["name"] = "Bebenbestienhauer", ["text"] = "Animabonus\n100 Meter Reichweite\nSofort\nWenn ein Gegner Euch Schaden zufügt, erleidet er (60% der Zaubermacht) Naturschaden. Wenn der Schaden mindestens 5% Eurer Gesundheit ausmacht, wird der Gegner zurückgestoßen.\n\nDer Rückstoß tritt pro Ziel nur einmal alle 10 Sek. auf." }
entries[297578] = { ["name"] = "Aufgeschobenes Urteil", ["text"] = "75 Meter Reichweite\nSofort\nEntfesselt angestaute Energie und verursacht Naturschaden, der davon abhängt, wie lange das Ziel stillgestanden hat." }
entries[297579] = { ["name"] = "Bebenbestienhauer", ["text"] = "Animabonus\n20 Meter Reichweite\nSofort\nWenn ein Gegner Euch Schaden zufügt, erleidet er (60% der Zaubermacht) Naturschaden. Wenn der Schaden mindestens 5% Eurer Gesundheit ausmacht, wird der Gegner zurückgestoßen.\n\nDer Rückstoß tritt pro Ziel nur einmal alle 10 Sek. auf." }
