entries[297584] = { ["name"] = "Zwicken", ["text"] = "Nahkampfreichweite\nWirken in 1.5 sek. 3 sek. Abklingzeit\nKneift einen Gegner und verursacht so körperlichen Schaden." }
entries[297585] = { ["name"] = "Gehorsam oder Leid", ["text"] = "Sofort\nAlle Spielercharaktere werden als Ziele des Leidens markiert. Wenn ein Spielercharakter Schaden erleidet, wird er mit ' Leid ' belegt, wodurch 5 Sek. lang sämtliche Heilung absorbiert wird.\n(10s Abklingzeit)" }
entries[297586] = { ["name"] = "Leid", ["text"] = "Sofort\nBelegt das Ziel mit einem Mal des Leidens, wodurch 5 Sek. lang sämtliche Heilung absorbiert wird." }
entries[297587] = { ["name"] = "Azeritwaffen", ["text"] = "Sofort\nErmöglicht dem Zaubernden, Azeritwaffen auszurüsten, was seinen verursachten Schaden um 50% erhöht.\n(3s Abklingzeit)" }
entries[297589] = { ["name"] = "Einheitenfenster für Eskorte" }
entries[297590] = { ["name"] = "Berntotem", ["text"] = "Sofort\nLässt eine Bernphiole fallen, die alle Verbündeten in der Nähe der Phiole Macht verleiht. Ihr verursachter Schaden wird um 20% erhöht und sie werden alle 5.2 Sek. geheilt. Hält 30 Sek. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden." }
